L["Tailoring"] = "Couture"
L["Take it off this card."] = "La retirer de cette carte."
L["Take it off this rule."] = "Le retirer de cette règle."
L["Takes off the piece before the cursor."] = "Retire l'élément avant le curseur."
L["Takes the bars out and brings them back in, as at a fight's start and end."] = "Retire les bandes et les ramène, comme au début et à la fin d'un combat."
L["Takes this icon off the wheel."] = "Retire cette icône de la roue."
L["Talent calculator"] = "Calculateur de talents"
