L["Transmog"] = "Transmo"
L["Triggers"] = "Déclencheurs"
L["Triggers: %s"] = "Déclencheurs : %s"
L["Trying %s. Close this window to keep it."] = "Essai de %s. Fermez cette fenêtre pour le garder."
L["Turn %d°   Tilt %d°   Zoom %s yd   %s / %s s"] = "Rotation %d°   Inclinaison %d°   Zoom %s m   %s / %s s"
L["Turn %s° toward where you clicked them over %s s"] = "Tourner de %s° vers là où vous avez cliqué en %s s"
L["Turn each move"] = "Rotation à chaque mouvement"
L["Turn it on to see and change its settings."] = "Activez-le pour voir et changer ses réglages."
