L["Vitals Vision demo: all %d shown."] = "Démo de Vitals Vision : les %d affichés."
L["Vitals Vision demo: no class called \"%s\"."] = "Démo de Vitals Vision : aucune classe nommée « %s »."
L["Vitals Vision shows it as far as your health says"] = "Vitals Vision l'affiche selon votre vie"
